def game_ends(board):
    s = sum(board)
    if s == 0:
        return True
    for x in board:
        if 2 * x > s:
            return True
    return False

memo = {}

def solve(board):
    board = tuple(sorted(board))
    if game_ends(board):
        return len(board)
    if board in memo:
        return memo[board]

    best_cookies = 0
    n = len(board)
    for i in range(n):
        for j in range(i + 1, n):
            x, y = board[i], board[j]

            res_for_this_pair = float('inf')
            for z in [x + y, abs(x - y)]:
                new_board = list(board)
                new_board.pop(j)
                new_board.pop(i)
                new_board.append(z)
                res_for_this_pair = min(res_for_this_pair, solve(tuple(new_board)))

            best_cookies = max(best_cookies, res_for_this_pair)

    memo[board] = best_cookies
    return best_cookies

